import sys
from collections import defaultdict

def main():
    sys.setrecursionlimit(1 << 25)
    n, m = map(int, sys.stdin.readline().split())
    adj = [[] for _ in range(n+1)]
    for _ in range(n-1):
        u, v = map(int, sys.stdin.readline().split())
        adj[u].append(v)
        adj[v].append(u)

    parent = [0]*(n+1)
    depth = [0]*(n+1)
    size = [0]*(n+1)
    heavy = [-1]*(n+1)

    def dfs(u):
        size[u] = 1
        max_size = 0
        for v in adj[u]:
            if v != parent[u]:
                parent[v] = u
                depth[v] = depth[u] + 1
                dfs(v)
                size[u] += size[v]
                if size[v] > max_size:
                    max_size = size[v]
                    heavy[u] = v

    dfs(1)

    head = [0]*(n+1)
    pos = [0]*(n+1)
    current_pos = 1

    def decompose(u, h):
        nonlocal current_pos
        head[u] = h
        pos[u] = current_pos
        current_pos += 1
        if heavy[u] != -1:
            decompose(heavy[u], h)
        for v in adj[u]:
            if v != parent[u] and v != heavy[u]:
                decompose(v, v)

    decompose(1, 1)

    bit = [defaultdict(int) for _ in range(n+2)]

    def update(pos, val):
        while pos <= n:
            bit[pos][val] += 1
            pos += pos & -pos

    def query(pos):
        res = defaultdict(int)
        while pos > 0:
            for k, v in bit[pos].items():
                res[k] += v
            pos -= pos & -pos
        return res

    res = [0]*(n+1)
    cnt = [0]*(n+1)

    for i in range(1, m+1):
        a, b = map(int, sys.stdin.readline().split())
        u = a
        while u != 0:
            update(pos[head[u]], i)
            u = parent[head[u]]
        u = b
        while u != 0:
            update(pos[head[u]], i)
            u = parent[head[u]]

    for u in range(1, n+1):
        cnt[u] = query(pos[u])
        for v in range(1, n+1):
            if v != u:
                q = query(pos[v])
                common = 0
                for k in cnt[u]:
                    if k in q:
                        common += 1
                res[u] += common

    for u in range(1, n+1):
        print(res[u], end=' ')
    print()

main()
